create table media_file
(
    id                 bigint auto_increment
        primary key,
    file_name          varchar(255)      not null comment '文件名',
    original_file_name varchar(255)      not null comment '原始文件名',
    file_type          varchar(50)       not null comment '文件类型（VIDEO/AUDIO）',
    content_type       varchar(100)      null comment '内容类型',
    file_size          bigint            not null comment '文件大小（字节）',
    file_path          varchar(500)      not null comment '存储路径',
    url                varchar(500)      not null comment '访问URL',
    upload_time        datetime          not null comment '上传时间',
    deleted            tinyint default 0 not null comment '逻辑删除标志(0-未删除，1-已删除)'
)
    comment '媒体文件表';

create index idx_file_type
    on media_file (file_type);

create index idx_upload_time
    on media_file (upload_time);

